"""Cross-platform preservation and copy-storage regressions; generated bytes only."""
from dataclasses import replace
from functools import lru_cache
import hashlib
import json
from pathlib import Path
import struct
import tempfile
import unittest
from unittest.mock import patch

from koei_editor import conversion as c
from koei_editor.games.dw3.models import SaveError
from koei_editor.shared.koei_codec import byte_cipher, mix_word, word_cipher, word_sum
from koei_editor.games.p5strikers_pc import codec as pc
from koei_editor.games.p5strikers_ps4 import codec as ps4
from koei_editor.games.p5strikers_ps4.context import title_only_sfo
from tests import test_ps3_expansion as ps3_context


@lru_cache(maxsize=12)
def fixture(endpoint_id, variant=0):
    if endpoint_id in ('dw6_xbox360_na', 'dw6_xbox360_eu'):
        from tests.test_dw6_xbox360_conversion import raw_fixture
        return raw_fixture(variant)
    if endpoint_id in ('dw6', 'dw6_ps3', 'dw6_ps3_jp', 'dw6_ps3_eu'):
        from tests.test_dw6_conversion import fixture as dw6_fixture
        return dw6_fixture(endpoint_id, variant)
    if endpoint_id.startswith('dw8xl'):
        payload = bytearray((i * 17 + variant) % 256 for i in range(0xB7F44))
        payload[:5] = bytes.fromhex('f002101309')
        checksum = bytes((sum(payload) & 255,))
        if endpoint_id == 'dw8xl_vita':
            return bytes(payload) + checksum
        if endpoint_id == 'dw8xl_ps4':
            return bytes(payload) + bytes(0x19001)
        inner = byte_cipher(bytes(payload), 0x13100200)
        if endpoint_id == 'dw8xl_ps3':
            return inner + checksum
        seed = 0xB221 + variant
        return struct.pack('<HH', word_sum(inner), seed) + word_cipher(inner, seed) + bytes((checksum[0] ^ (mix_word(seed) & 255),))
    size = c.ENDPOINTS[endpoint_id].backend.SAVE_SIZE
    payload = bytearray(size)
    payload[:ps4.SLOTS_END] = bytes((i * 23 + variant) % 256 for i in range(ps4.SLOTS_END))
    payload[:4] = ps4.VERSION_BYTES
    payload[4:8] = (variant % 10).to_bytes(4, 'little')
    for slot in range(10):
        base = ps4.HEADER_SIZE + slot * ps4.SLOT_SIZE
        payload[base + ps4.MARKER_RELATIVE:base + ps4.MARKER_RELATIVE + 4] = ps4.LAYOUT_MARKER.to_bytes(4, 'little')
    if endpoint_id == 'p5strikers_pc':
        return pc.encode(pc.with_checksum(bytes(payload)), 0x123456 + variant)
    return bytes(payload)


def write_copy(folder, endpoint_id, variant=0):
    folder.mkdir(parents=True)
    endpoint = c.ENDPOINTS[endpoint_id]
    path = folder / endpoint.filename
    path.write_bytes(fixture(endpoint_id, variant))
    if endpoint.companion:
        companion = folder / endpoint.companion
        companion.parent.mkdir(parents=True, exist_ok=True)
        if endpoint_id in ('dw6_xbox360_na', 'dw6_xbox360_eu'):
            from tests.test_dw6_xbox360_conversion import context_fixture
            metadata = context_fixture(endpoint_id, fixture(endpoint_id, variant), variant)
        elif endpoint_id in ('dw8xl_ps3', 'dw6_ps3', 'dw6_ps3_jp', 'dw6_ps3_eu'):
            metadata = ps3_context.PS3ContextTests.metadata({
                'dw8xl_ps3': 'NPUB31449-SAVEDATA', 'dw6_ps3': 'BLUS30110-SAVEDATA',
                'dw6_ps3_jp': 'BLJM60041-SAVEDATA',
                'dw6_ps3_eu': 'BLES00215-SAVEDATA',
            }[endpoint_id])
        else:
            metadata = title_only_sfo()
            if endpoint_id == 'dw8xl_ps4':
                metadata = metadata.replace(b'CUSA19640', b'CUSA00397')
        companion.write_bytes(metadata)
    return path


class ConversionTests(unittest.TestCase):
    def test_endpoints_are_exact_registered_adapters_and_routes_are_family_scoped(self):
        from koei_editor.game_registry import get_game
        for endpoint in c.ENDPOINTS.values():
            if endpoint.conversion_only:
                self.assertIn(endpoint.id, ('dw8xl_ps4', 'dw6_ps3_jp', 'dw6_ps3_eu',
                                            'dw6_xbox360_na', 'dw6_xbox360_eu'))
                with self.assertRaises(SaveError):
                    get_game(endpoint.id)
                continue
            game = get_game(endpoint.id)
            self.assertIs(game.get_scalar_adapter().backend, endpoint.backend)
            self.assertEqual(game.extension, Path(endpoint.filename).suffix.lower())
        self.assertEqual(len({route.id for route in c.ROUTES}), len(c.ROUTES))
        for route in c.ROUTES:
            self.assertNotEqual(route.source_id, route.target_id)
            self.assertEqual(c.ENDPOINTS[route.source_id].family, c.ENDPOINTS[route.target_id].family)

    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.folder = Path(self.temp.name)

    def prepare(self, source='dw8xl', target='dw8xl_vita'):
        source_path = write_copy(self.folder / 'source', source)
        template_path = write_copy(self.folder / 'template', target, 1)
        return c.prepare(source + '-to-' + target, source_path, template_path)

    def test_every_route_export_preserves_gameplay_and_destination_context(self):
        for index, route in enumerate(c.ROUTES):
            with self.subTest(route=route.id):
                source = write_copy(self.folder / str(index) / 'source', route.source_id)
                template = write_copy(self.folder / str(index) / 'template', route.target_id, 1)
                original, original_template = source.read_bytes(), template.read_bytes()
                conversion = c.prepare(route.id, source, template)
                output = self.folder / str(index) / 'export'
                path, backups, receipt = c.export(conversion, output)
                target = c.ENDPOINTS[route.target_id]
                reopened = target.backend.read_save(path, route.target_id)
                self.assertEqual(c._gameplay(c.Snapshot(route.target_id, reopened), route), c._gameplay(conversion.source, route))
                self.assertEqual(source.read_bytes(), original)
                self.assertEqual(template.read_bytes(), original_template)
                self.assertEqual([p.read_bytes() for p in backups], [original, original_template])
                if hasattr(reopened, 'seed'):
                    self.assertEqual(reopened.seed, conversion.template.document.seed)
                if target.companion:
                    self.assertEqual((output / target.companion).read_bytes(), conversion.template.companion_raw)
                self.assertEqual(receipt, json.loads((output / 'conversion.json').read_text()))
                self.assertEqual(receipt['output_sha256'], hashlib.sha256(path.read_bytes()).hexdigest())
                self.assertFalse(receipt['game_load_verified'])
                self.assertNotIn(str(self.folder), json.dumps(receipt))
                reverse = c.prepare(route.target_id + '-to-' + route.source_id, path, source)
                self.assertEqual(reverse.raw, original)

    def test_readonly_prepare_has_no_backups_or_output(self):
        conversion = self.prepare()
        self.assertFalse(any(self.folder.rglob('*.json')))
        self.assertNotIn('Snapshot', repr(conversion))
        self.assertNotIn(str(conversion.source.document.raw[:100]), repr(conversion))

    def test_changed_source_or_template_and_context_never_exports(self):
        for kind in ('source', 'template', 'metadata'):
            with self.subTest(kind=kind), tempfile.TemporaryDirectory() as directory:
                source = write_copy(Path(directory) / 'source', 'dw8xl')
                template = write_copy(Path(directory) / 'template', 'dw8xl_ps3')
                conversion = c.prepare('dw8xl-to-dw8xl_ps3', source, template)
                changed = source if kind == 'source' else template if kind == 'template' else template.parent / 'PARAM.SFO'
                changed.write_bytes(changed.read_bytes() + b'\0')
                with self.assertRaises((OSError, SaveError)):
                    c.export(conversion, Path(directory) / 'out')
                self.assertFalse((Path(directory) / 'out').exists())

    def test_race_during_backup_is_rechecked_before_any_output(self):
        conversion = self.prepare()
        backend = c.ENDPOINTS['dw8xl'].backend
        original = backend.backup
        def racing(document):
            backup = original(document)
            document.source.write_bytes(document.raw + b'!')
            return backup
        with patch.object(backend, 'backup', side_effect=racing), self.assertRaises(SaveError):
            c.export(conversion, self.folder / 'output')
        self.assertFalse((self.folder / 'output').exists())

    def test_existing_empty_folders_files_and_aliases_never_replaced(self):
        conversion = self.prepare()
        output = self.folder / 'output'
        output.mkdir()
        with self.assertRaises(FileExistsError): c.export(conversion, output)
        self.assertEqual(list(output.iterdir()), [])
        with self.assertRaises(FileExistsError): c.export(conversion, conversion.source.document.source.parent)
        with self.assertRaises(FileExistsError): c.export(conversion, conversion.source.document.source)

    def test_mutated_plans_and_foreign_routes_are_rejected(self):
        conversion = self.prepare()
        for forged in (replace(conversion, raw=conversion.raw[:-1]),
                       replace(conversion, gameplay_sha256='0' * 64),
                       replace(conversion, gameplay_bytes=0),
                       replace(conversion, route=c.Route('dw8xl', 'p5strikers_pc')),
                       replace(conversion, template=conversion.source), replace(conversion, route=None),
                       replace(conversion, source=None), replace(conversion, raw=bytearray(conversion.raw)),
                       replace(conversion, route=c.Route([], 'dw8xl_vita'))):
            with self.subTest(kind=forged.route), self.assertRaises(SaveError): c.export(forged, self.folder / 'out')
        for route in ('dw6-to-dw8xl_ps3', 'dw8xl-to-dw8xl', 'unknown', None):
            with self.assertRaises(SaveError): c.get_route(route)

    def test_failed_actual_readback_retains_incomplete_output_without_receipt(self):
        conversion = self.prepare()
        original = c._read
        def damaged(endpoint, path):
            # Windows TEMP can use an 8.3 alias while safe_path returns the
            # long spelling. Inject into the same resolved destination.
            if Path(path).resolve().parent == (self.folder / 'output').resolve():
                raise SaveError('Injected destination read-back failure')
            return original(endpoint, path)
        with patch.object(c, '_read', side_effect=damaged), self.assertRaises(SaveError):
            c.export(conversion, self.folder / 'output')
        self.assertEqual((self.folder / 'output' / 'MainData00.dat').read_bytes(), conversion.raw)
        self.assertFalse((self.folder / 'output' / 'conversion.json').exists())

    def test_nonzero_pc_tail_is_not_silently_discarded(self):
        source = write_copy(self.folder / 'source', 'p5strikers_pc')
        template = write_copy(self.folder / 'template', 'p5strikers_switch')
        doc = pc.decode(source.read_bytes())
        payload = bytearray(doc.payload)
        payload[ps4.SLOTS_END + 2] = 4
        source.write_bytes(pc.encode(pc.with_checksum(bytes(payload)), doc.state))
        with self.assertRaisesRegex(SaveError, 'discard'):
            c.prepare('p5strikers_pc-to-p5strikers_switch', source, template)

    def test_pc_destination_opaque_tail_and_seed_preserved(self):
        source = write_copy(self.folder / 'source', 'p5strikers_switch')
        template = write_copy(self.folder / 'template', 'p5strikers_pc', 1)
        doc = pc.decode(template.read_bytes())
        payload = bytearray(doc.payload)
        payload[ps4.SLOTS_END + 2] = 4
        template.write_bytes(pc.encode(pc.with_checksum(bytes(payload)), doc.state))
        result = c.prepare('p5strikers_switch-to-p5strikers_pc', source, template)
        actual = pc.decode(result.raw)
        self.assertEqual(actual.payload[ps4.SLOTS_END:-4], bytes(payload)[ps4.SLOTS_END:-4])
        self.assertEqual(actual.state, doc.state)

    def test_damaged_inputs_and_missing_or_foreign_metadata_rejected(self):
        source = write_copy(self.folder / 'source', 'dw8xl')
        template = write_copy(self.folder / 'template', 'dw8xl_ps3')
        source.write_bytes(source.read_bytes()[:-1])
        with self.assertRaises(SaveError): c.prepare('dw8xl-to-dw8xl_ps3', source, template)
        source.write_bytes(fixture('dw8xl'))
        metadata = template.parent / 'PARAM.SFO'
        metadata.write_bytes(ps3_context.PS3ContextTests.metadata('BLUS30110-SAVEDATA'))
        with self.assertRaises(SaveError): c.prepare('dw8xl-to-dw8xl_ps3', source, template)
        metadata.unlink()
        with self.assertRaises(OSError): c.prepare('dw8xl-to-dw8xl_ps3', source, template)

    def test_modded_pc_revision_is_not_normalized(self):
        source = write_copy(self.folder / 'source', 'dw8xl')
        template = write_copy(self.folder / 'template', 'dw8xl_vita')
        doc = c.ENDPOINTS['dw8xl'].backend.decode(source.read_bytes(), 'dw8xl')
        payload = bytes.fromhex('f027021909') + doc.payload[5:]
        inner = byte_cipher(payload, 0x13100200)
        source.write_bytes(struct.pack('<HH', word_sum(inner), doc.seed) + word_cipher(inner, doc.seed)
                           + bytes(((sum(payload) & 255) ^ (mix_word(doc.seed) & 255),)))
        with self.assertRaisesRegex(SaveError, 'revision'):
            c.prepare('dw8xl-to-dw8xl_vita', source, template)
